let target = null;
let gx = 0;
let gy = 0;
const BOOST = 6;
const MIN_D = 0.15;
return {
  onInit() {
    if (ctx.bindings.thisId != null) { target = ctx.bindings.thisId; }
    else {
      let ids = ctx.entities();
      for (let id of ids) { target = id; break; }
    }
  },
  onGrab(id) {
    if (id !== target) { return; }
    let e = ctx.entity(id);
    if (e == null) { return; }
    gx = e.x;
    gy = e.y;
  },
  onRelease(id) {
    if (id !== target) { return; }
    let e = ctx.entity(id);
    if (e == null) { return; }
    let dx = e.x - gx;
    let dy = e.y - gy;
    let d = Math.sqrt(dx * dx + dy * dy);
    if (!(d > MIN_D)) { return; }
    let vx = dx * BOOST;
    let vy = dy * BOOST;
    ctx.setVelocity(id, e.vx + vx, e.vy + vy);
    ctx.log("slingshot", id, d);
  }
};

let targetId = null;
let grabX = 0;
let grabY = 0;
let hasGrab = false;
return {
  onGrab(id) {
    if (id === "truck") {
      targetId = id;
      let e = ctx.entity(id);
      if (e != null) { grabX = e.x; grabY = e.y; hasGrab = true; }
    }
  },
  onRelease(id) {
    if (id === "truck" && hasGrab) {
      let e = ctx.entity(id);
      if (e != null) {
        let dx = e.x - grabX;
        let dy = e.y - grabY;
        let gain = 8;
        let nvx = 0 - dx * gain;
        let nvy = 0 - dy * gain;
        if (nvx > 20) { nvx = 20; }
        if (nvx < -20) { nvx = -20; }
        if (nvy > 20) { nvy = 20; }
        if (nvy < -20) { nvy = -20; }
        if (dx * dx + dy * dy > 0.04) {
          ctx.setVelocity(id, e.vx + nvx, e.vy + nvy);
        }
      }
      hasGrab = false;
    }
  }
};

let targetId = null;
let startX = 0;
let startY = 0;
let lastX = 0;
let lastY = 0;
let holding = false;
return {
  onInit() {
    let b = ctx.bindings;
    if (b.thisId != null) { targetId = b.thisId; }
    else {
      let f = ctx.find("truck");
      for (let id of f) { targetId = id; }
    }
  },
  onGrab(id) {
    if (id === targetId) {
      let e = ctx.entity(id);
      if (e != null) {
        startX = e.x;
        startY = e.y;
        lastX = e.x;
        lastY = e.y;
        holding = true;
      }
    }
  },
  onStep(dt) {
    if (targetId == null) { return; }
    let e = ctx.entity(targetId);
    if (e == null) { return; }
    if (e.held) {
      holding = true;
      lastX = e.x;
      lastY = e.y;
    }
  },
  onRelease(id) {
    if (id === targetId) {
      let e = ctx.entity(id);
      if (e == null) { return; }
      let dx = lastX - startX;
      let dy = lastY - startY;
      let k = 6;
      let nvx = 0 - dx * k;
      let nvy = 0 - dy * k;
      if (nvx > 12) { nvx = 12; }
      if (nvx < -12) { nvx = -12; }
      if (nvy > 12) { nvy = 12; }
      if (nvy < -12) { nvy = -12; }
      if (dx > -0.2 && dx < 0.2 && dy > -0.2 && dy < 0.2) { holding = false; return; }
      ctx.setVelocity(id, nvx, nvy);
      holding = false;
      ctx.log("slingshot", nvx, nvy);
    }
  }
};

let sx = 0;
let sy = 0;
let hasGrab = false;
let grabId = "";
return {
  onGrab(id) {
    let e = ctx.entity(id);
    if (e == null) { return; }
    sx = e.x;
    sy = e.y;
    grabId = id;
    hasGrab = true;
  },
  onRelease(id) {
    let e = ctx.entity(id);
    if (e == null) { return; }
    if (!e.dynamic) { return; }
    let vx = e.vx;
    let vy = e.vy;
    if (!isFinite(vx)) { vx = 0; }
    if (!isFinite(vy)) { vy = 0; }
    if (hasGrab) {
      let dx = e.x - sx;
      let dy = e.y - sy;
      hasGrab = false;
      let wantVx = dx * 10;
      let wantVy = dy * 10;
      let bvVx = vx * 8;
      let bvVy = vy * 8;
      let useVx = wantVx;
      let useVy = wantVy;
      let wSp = Math.sqrt(wantVx * wantVx + wantVy * wantVy);
      let bSp = Math.sqrt(bvVx * bvVx + bvVy * bvVy);
      if (bSp > wSp) { useVx = bvVx; useVy = bvVy; }
      let sp = Math.sqrt(useVx * useVx + useVy * useVy);
      if (sp < 25) {
        let s = 25 / (sp + 0.001);
        useVx = useVx * s;
        useVy = useVy * s;
      }
      ctx.setVelocity(id, useVx, useVy);
    } else {
      ctx.setVelocity(id, vx * 8, vy * 8);
    }
    ctx.log('slingshot', id);
  }
};

let done = false;
return {
  onInit() {
    ctx.setGravity(0, 1.62);
    done = true;
    ctx.log('moon gravity');
  },
  onStep(dt) {
    if (done === false) { ctx.setGravity(0, 1.62); done = true; }
  }
};

let DONE = false;
return {
  onInit() {
    ctx.setGravity(0, 1.62);
    ctx.log('moon gravity on');
  },
  onStep(dt) {
    if (!DONE) { ctx.setGravity(0, 1.62); DONE = true; }
