let ids = [];
return {
  onInit() {
    ids = ctx.entities();
    for (let id of ids) {
      let e = ctx.entity(id);
      if (e != null) { ctx.setRestitution(id, 1.2); }
    }
    ctx.log('super bouncy on');
  },
  onCollision(e) {
    let id = e.a;
    if (id == 'ground') { id = e.b; }
    if (id == 'ground') { return; }
    let v = ctx.entity(id);
    if (v == null) { return; }
    if (v.held) { return; }
    ctx.setRestitution(id, 1.2);
    let kick = e.speed * 1.2;
    if (kick < 7) { kick = 7; }
    ctx.setVelocity(id, v.vx, -kick);
  }
};

let IDS = [];
return {
 onInit() {
