let ids = [];
return {
  onInit() {
    ids = ctx.entities();
    for (const id of ids) {
      const e = ctx.entity(id);
      if (e != null && e.dynamic) { ctx.setRestitution(id, 1.2); }
    }
    ctx.log('super bouncy on');
  },
  onStep(dt) {
    for (const id of ids) {
      const e = ctx.entity(id);
      if (e != null && e.dynamic && e.restitution < 1.2) { ctx.setRestitution(id, 1.2); }
    }
  }
};

let ids = [];
return {
  onInit() {
    ids = ctx.entities();
    for (const id of ids) {
      const e = ctx.entity(id);
      if (e == null) continue;
      ctx.setRestitution(id, 1.1);
    }
    ctx.log('everything super bouncy');
  },
  onStep(dt) {
