let ids = [];
return {
  onInit() {
    ids = ctx.find("cone");
    for (const id of ids) {
      ctx.setAngularVelocity(id, 12);
    }
    ctx.log("spinning cones");
  },
  onStep(dt) {
    for (const id of ids) {
      const e = ctx.entity(id);
      if (e == null) continue;
      if (e.held) continue;
      if (Math.abs(e.angularVelocity) < 8) {
        ctx.setAngularVelocity(id, 12);
      }
    }
  }
};

const a = "cone_1";
const b = "cone_2";
function spin() {
  ctx.setAngularVelocity(a, 12);
  ctx.setAngularVelocity(b, 12);
}
return {
  onInit() { spin(); },
  onStep(dt) { spin(); }
};

let ids = [];
return {
  onInit() {
    ids = ctx.find("cone");
    for (let id of ids) { ctx.setAngularVelocity(id, 12); }
    ctx.log("spinning cones");
  },
  onStep(dt) {
    for (let id of ids) {
      let e = ctx.entity(id);
      if (e == null) continue;
      if (e.held) continue;
      let w = e.angularVelocity;
      if (w < 8) ctx.setAngularVelocity(id, 12);
    }
  }
};

let SPIN = 12;
function spinAll() {
  let ids = ctx.find("cone");
  for (let id of ids) {
    let e = ctx.entity(id);
    if (e == null) continue;
    if (!e.dynamic) continue;
    ctx.setAngularVelocity(id, SPIN);
  }
}
return {
  onInit() { spinAll(); },
  onStep(dt) { spinAll(); }
};

let ids = [];
return {
  onInit() {
    let found = ctx.find('cone');
    for (let id of found) { ids.push(id); }
    for (let id of ctx.bindings.named) {
      let dup = false;
      for (let q of ids) { if (q === id) { dup = true; } }
      if (!dup) { ids.push(id); }
    }
    for (let id of ids) {
      let e = ctx.entity(id);
      if (e != null) { ctx.setAngularVelocity(id, 12); }
    }
    ctx.log('spinning cones');
  },
  onStep(dt) {
    for (let id of ids) {
      let e = ctx.entity(id);
      if (e == null) { continue; }
      let w = e.angularVelocity;
      if (w < 8) { ctx.setAngularVelocity(id, 12); }
    }
  }
};

let base = 0;
return {
  onInit() {
    let e = ctx.entity("truck");
    if (e == null) return;
    base = e.mass;
    ctx.setMass("truck", base * 10);
    ctx.log("truck mass x10");
  }
