let ids = [];
return {
 onInit() {
  let all = ctx.entities();
  for (let id of all) {
   let e = ctx.entity(id);
   if (e != null && e.dynamic) { ids.push(id); ctx.setVelocity(id, 0, -12); }
  }
  ctx.log('launched ' + ids.length + ' bodies');
 },
 onStep(dt) {}
};

let done = false;
return {
  onInit() {
    const ids = ctx.entities();
    for (const id of ids) {
      const e = ctx.entity(id);
      if (e == null) continue;
      if (!e.dynamic) continue;
      const up = 8 + ctx.random() * 3;
      const side = (ctx.random() - 0.5) * 2;
      ctx.applyImpulse(id, e.mass * side, -e.mass * up);
    }
    done = true;
    ctx.log('launch!');
  }
};

let launched = false;
return {
  onInit() {
    const ids = ctx.entities();
    for (const id of ids) {
      const e = ctx.entity(id);
      if (e == null) { continue; }
      if (!e.dynamic) { continue; }
      ctx.applyImpulse(id, 0, 0 - e.mass * 9);
    }
    launched = true;
    ctx.log('launch!');
  }
};

let ids = [];
return {
  onInit() {
    const all = ctx.entities();
    for (const id of all) {
      const e = ctx.entity(id);
      if (e == null) { continue; }
      if (!e.dynamic) { continue; }
      ids.push(e.id);
    }
    for (const id of ids) {
      ctx.setVelocity(id, 0, -12);
    }
    ctx.log('launched ' + ids.length + ' bodies');
  }
};

let launched = false;
return {
  onInit() {
    if (launched) return;
    launched = true;
    const ids = ctx.entities();
    for (const id of ids) {
      const e = ctx.entity(id);
      if (e == null) continue;
      if (!e.dynamic) continue;
      ctx.setVelocity(id, e.vx, -12);
    }
    ctx.log('launched everything');
  }
};

