const BALL = "ball";
let boost = 0;
return {
  onInit() {
    ctx.setRestitution(BALL, 0);
  },
  onCollision(e) {
    let isBall = (e.a === BALL) || (e.b === BALL);
    if (!isBall) return;
    let other = (e.a === BALL) ? e.b : e.a;
    if (other !== "ground") return;
    let v = e.speed * 1.42;
    if (!(v > 2)) v = 2;
    boost = v;
    ctx.log("boost", v);
  },
  onStep(dt) {
    if (boost <= 0) return;
    let b = ctx.entity(BALL);
    if (b == null) return;
    if (b.vy > -boost) {
      ctx.setVelocity(BALL, b.vx, -boost);
    } else {
      boost = 0;
    }
  }
};

let ballId = null;
return {
  onInit() {
    let ids = ctx.find("ball");
    for (let id of ids) { ballId = id; }
    if (ballId == null) {
      let all = ctx.entities();
      for (let id of all) { ballId = id; }
    }
  },
  onCollision(e) {
    if (ballId == null) { return; }
    let hitBall = (e.a === ballId || e.b === ballId);
    if (!hitBall) { return; }
    let other = e.a === ballId ? e.b : e.a;
    if (other !== "ground") { return; }
    let v = ctx.entity(ballId);
    if (v == null) { return; }
    let up = e.speed * 1.5;
    if (!(up > 2)) { up = 2; }
    ctx.setVelocity(ballId, v.vx, -up);
    ctx.log("boost", up);
  }
};

let BOOST = 1.42;
return {
  onCollision(e) {
    let isBall = (e.a === "ball" || e.b === "ball");
    if (!isBall) { return; }
    let hitGround = (e.a === "ground" || e.b === "ground");
    if (!hitGround) { return; }
    let b = ctx.entity("ball");
    if (b == null) { return; }
    let s = e.speed;
    if (!(s > 0.5)) { return; }
    ctx.setVelocity("ball", b.vx, 0 - s * BOOST);
    ctx.log("super bounce", s);
  }
};

let ballId = null;
return {
 onInit() {
  let ids = ctx.bindings.named;
  if (ids.length > 0) { ballId = ids[0]; } else { let f = ctx.find("ball"); if (f.length > 0) { ballId = f[0]; } }
 },
 onCollision(e) {
  if (ballId == null) { return; }
  let isBall = (e.a === ballId || e.b === ballId);
  if (!isBall) { return; }
  let other = (e.a === ballId) ? e.b : e.a;
  if (other !== "ground") { return; }
  if (!(e.speed > 0.5)) { return; }
  let b = ctx.entity(ballId);
  if (b == null) { return; }
  let vx = b.vx;
  let vyUp = 0 - e.speed * 1.5;
  ctx.setVelocity(ballId, vx, vyUp);
 }
};

let ballId = "ball";
return {
  onInit() {
    let f = ctx.find("rubber_ball");
    for (let id of f) { ballId = id; }
    if (ctx.bindings.named.length > 0) { ballId = ctx.bindings.named[0]; }
  },
  onCollision(e) {
    let isBall = (e.a === ballId || e.b === ballId);
    let hitsGround = (e.a === "ground" || e.b === "ground");
    if (isBall && hitsGround) {
      let b = ctx.entity(ballId);
      if (b == null) { return; }
      let up = e.speed * 1.45;
      if (up < 3) { up = 3; }
      ctx.setVelocity(ballId, b.vx, -up);
      ctx.log("double bounce", up);
    }
  }
};
